drop policy if exists delivery_assignments_staff_all on public.delivery_assignments; create policy delivery_assignments_scoped_select on public.delivery_assignments for select to authenticated using ((select is_admin()) or assigned_staff_id = (select auth.uid())); create policy delivery_assignments_scoped_insert on public.delivery_assignments for insert to authenticated with check ((select is_admin()) or assigned_staff_id = (select auth.uid())); create policy delivery_assignments_scoped_update on public.delivery_assignments for update to authenticated using ((select is_admin()) or assigned_staff_id = (select auth.uid())) with check ((select is_admin()) or assigned_staff_id = (select auth.uid())); create policy delivery_assignments_scoped_delete on public.delivery_assignments for delete to authenticated using ((select is_admin()) or assigned_staff_id = (select auth.uid())); drop policy if exists staff_select on public.staff; create policy staff_select on public.staff for select to authenticated using ((select is_admin()) or id = (select auth.uid())); drop policy if exists delivery_proofs_select on public.delivery_proofs; create policy delivery_proofs_select on public.delivery_proofs for select to authenticated using (((select is_admin()) or exists (select 1 from public.delivery_assignments da where da.proof_id = delivery_proofs.id and da.assigned_staff_id = (select auth.uid()))) or exists (select 1 from public.shipments s where s.id = delivery_proofs.shipment_id and s.customer_user_id = (select auth.uid()))); drop policy if exists staff_permissions_self_read on public.staff_permissions; create policy staff_permissions_self_read on public.staff_permissions for select to authenticated using ((staff_id = (select auth.uid())) or (select is_admin())); create index if not exists idx_staff_permissions_granted_by on public.staff_permissions(granted_by);;
